DROP PROCEDURE IF EXISTS add_migration;
DELIMITER ??
CREATE PROCEDURE `add_migration`()
BEGIN
DECLARE v INT DEFAULT 1;
SET v = (SELECT COUNT(*) FROM `migrations` WHERE `id`='20261018170000');
IF v = 0 THEN

DELETE FROM `bonk_mob_ability` WHERE `spell_id` IN (6545, 25425, 1698, 28863) AND `entry` IN (315, 412, 522, 534, 639, 644, 646, 647, 680, 728, 730, 731, 1853, 2606, 2609, 2611, 2748, 2793, 3394, 3395, 3396, 4421, 4854, 5709, 5715, 6581, 6583, 6584, 7228, 7271, 7273, 7291, 7795, 8127, 8443, 8580, 8983, 9017, 9019, 9033, 9196, 9237, 9464, 9517, 9568, 9622, 9816, 9877, 10220, 10363, 10429, 10430, 10435, 10438, 10439, 10440, 10506, 10507, 10508, 10813, 10997, 11380, 11486, 11487, 11489, 11492, 11496, 11501, 11622, 11982, 12057, 12118, 12201, 12203, 12236, 12258, 12259, 12397, 14467, 14507, 14510, 14834, 15339, 15340, 15341, 15348, 15369, 15370);

UPDATE `bonk_mob_ability` SET `max_range` = 30 WHERE `spell_id` IN (22911, 6268) AND `max_range` < 30;

END IF;
END??
DELIMITER ;
CALL add_migration();
DROP PROCEDURE IF EXISTS add_migration;
